const $=s=>document.querySelector(s);
const copy={
uk:{title:'Доставка й оплата',contact:'Одержувач',name:'Ім’я та прізвище',phone:'Телефон',delivery:'Доставка',city:'Місто / населений пункт',branch:'Відділення або поштомат',postcode:'Поштовий індекс відділення',payment:'Оплата',cod:'Післяплата',card:'Онлайн карткою',soon:'Готується до запуску',note:'Комісія за післяплату та доставка оплачуються окремо за тарифами перевізника.',comment:'Коментар до замовлення',review:'Перевірити замовлення',back:'Редагувати',total:'Товари',shipping:'Доставка',tariff:'За тарифами перевізника',pending:'Це перевірка даних, не підтверджене замовлення. Прийом замовлень ще готується до запуску.',contactShop:'Зателефонувати магазину',empty:'Спочатку додайте товар до кошика.',lookup:'Знайти відділення',unavailable:'Автоматичний пошук ще не підключено. Вкажіть відділення вручну.',error:'Не вдалося завантажити відділення. Спробуйте ще раз.',choose:'Оберіть відділення',invalid:'Перевірте український номер телефону.',stock:'Кількість або товар змінилися. Поверніться до кошика.',privacy:'Дані поки залишаються на цій сторінці й не надсилаються магазину.'},
ru:{title:'Доставка и оплата',contact:'Получатель',name:'Имя и фамилия',phone:'Телефон',delivery:'Доставка',city:'Город / населённый пункт',branch:'Отделение или почтомат',postcode:'Почтовый индекс отделения',payment:'Оплата',cod:'Наложенный платёж',card:'Онлайн картой',soon:'Готовится к запуску',note:'Комиссия за наложенный платёж и доставка оплачиваются отдельно по тарифам перевозчика.',comment:'Комментарий к заказу',review:'Проверить заказ',back:'Редактировать',total:'Товары',shipping:'Доставка',tariff:'По тарифам перевозчика',pending:'Это проверка данных, не подтверждённый заказ. Приём заказов ещё готовится к запуску.',contactShop:'Позвонить в магазин',empty:'Сначала добавьте товар в корзину.',lookup:'Найти отделение',unavailable:'Автоматический поиск ещё не подключён. Укажите отделение вручную.',error:'Не удалось загрузить отделения. Попробуйте ещё раз.',choose:'Выберите отделение',invalid:'Проверьте украинский номер телефона.',stock:'Количество или товар изменились. Вернитесь в корзину.',privacy:'Данные пока остаются на этой странице и не отправляются магазину.'},
en:{title:'Delivery & payment',contact:'Recipient',name:'Full name',phone:'Phone',delivery:'Delivery',city:'City / town',branch:'Branch or parcel locker',postcode:'Branch postal code',payment:'Payment',cod:'Cash on delivery',card:'Online by card',soon:'Coming soon',note:'Shipping and cash-on-delivery fees are charged separately at the carrier’s rates.',comment:'Order notes',review:'Review order',back:'Edit',total:'Products',shipping:'Shipping',tariff:'Carrier’s rates',pending:'This is a review, not a confirmed order. Order acceptance is being prepared.',contactShop:'Call the shop',empty:'Add a product to your cart first.',lookup:'Find branch',unavailable:'Automatic lookup is not connected yet. Enter the branch manually.',error:'Could not load branches. Try again.',choose:'Choose a branch',invalid:'Check your Ukrainian phone number.',stock:'A product or quantity has changed. Return to your cart.',privacy:'Your details remain on this page and are not sent to the shop.'}};
let lang='uk',rows=[],catalog=[],draft={},config={nova:false,ukr:false};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat(lang==='uk'?'uk-UA':lang==='ru'?'ru-RU':'en-GB').format(x)+' ₴';
const readCart=()=>{try{return JSON.parse(localStorage.getItem('kari-cart')||'[]')}catch{return []}};
const c=()=>copy[lang];
function items(){return rows.map(r=>{const p=catalog.find(p=>p.id===r.product),v=p?.variants.find(v=>v.id===r.variant);return p&&v?{...r,p,v}:null}).filter(Boolean)}
function summary(){return '<div class="order-items">'+items().map(x=>'<div><img src="'+esc(x.p.image)+'" alt=""><span>'+esc(x.p[lang])+'<small>'+esc(x.v[lang])+(x.pillow?' · '+esc(x.pillow):'')+' × '+x.qty+'</small></span><strong>'+money(x.v.price*x.qty)+'</strong></div>').join('')+'</div><div class="order-total"><span>'+c().total+'</span><strong>'+money(items().reduce((n,x)=>n+x.qty*x.v.price,0))+'</strong></div><div class="order-shipping"><span>'+c().shipping+'</span><span>'+c().tariff+'</span></div>'}
function field(name,label,extra=''){return '<label>'+label+'<input name="'+name+'" '+extra+' value="'+esc(draft[name]||'')+'"></label>'}
function render(){
 const t=c();
 $('#checkout-content').innerHTML='<p class="eyebrow">KARI-SAN</p><h2 id="checkout-title">'+t.title+'</h2><form id="checkout-form"><div class="checkout-grid"><div><fieldset><legend>01 · '+t.contact+'</legend>'+field('name',t.name,'required minlength="3" maxlength="100" autocomplete="name"')+field('phone',t.phone,'type="tel" required maxlength="25" autocomplete="tel" placeholder="+380"')+'</fieldset><fieldset><legend>02 · '+t.delivery+'</legend><div class="checkout-options"><label><input type="radio" name="carrier" value="nova" checked>Нова пошта</label><label><input type="radio" name="carrier" value="ukr">Укрпошта</label></div>'+field('city',t.city,'required maxlength="100" autocomplete="address-level2"')+field('postcode',t.postcode,'inputmode="numeric" pattern="[0-9]{5}" maxlength="5"')+'<button type="button" id="lookup-branch" class="checkout-secondary">'+t.lookup+'</button><p id="delivery-status" role="status"></p><label id="branch-options-label" hidden>'+t.choose+'<select id="branch-options"><option value="">—</option></select></label>'+field('branch',t.branch,'required maxlength="200"')+'</fieldset><fieldset><legend>03 · '+t.payment+'</legend><div class="checkout-options"><label><input type="radio" name="payment" value="cod" checked>'+t.cod+'</label><label class="payment-pending"><input type="radio" name="payment" value="card" disabled>'+t.card+'<small>'+t.soon+'</small></label></div><p class="checkout-help">'+t.note+'</p></fieldset><label>'+t.comment+'<textarea name="comment" rows="3" maxlength="500">'+esc(draft.comment||'')+'</textarea></label></div><aside class="checkout-summary">'+summary()+'<p class="checkout-help">'+t.privacy+'</p><button class="checkout-start" type="submit">'+t.review+'</button></aside></div></form>';
 const form=$('#checkout-form');if(draft.carrier)form.elements.carrier.value=draft.carrier;
 function change(){const ukr=form.elements.carrier.value==='ukr';form.elements.postcode.closest('label').hidden=!ukr;form.elements.postcode.required=ukr;$('#delivery-status').textContent=config[ukr?'ukr':'nova']?'':t.unavailable;$('#lookup-branch').disabled=!config[ukr?'ukr':'nova'];$('#branch-options-label').hidden=true}
 change();form.elements.carrier.forEach(r=>r.addEventListener('change',()=>{form.elements.branch.value='';change()}));
 $('#lookup-branch').addEventListener('click',async()=>{const carrier=form.elements.carrier.value,q=carrier==='ukr'?form.elements.postcode.value:form.elements.city.value;if(!q)return;const button=$('#lookup-branch');button.disabled=true;try{const res=await fetch('/api/delivery?carrier='+carrier+'&q='+encodeURIComponent(q));if(!res.ok)throw Error();const data=await res.json();$('#branch-options').innerHTML='<option value="">'+t.choose+'</option>'+data.branches.map(b=>'<option value="'+esc(b.label)+'">'+esc(b.label)+'</option>').join('');$('#branch-options-label').hidden=false;$('#delivery-status').textContent=data.branches.length?'':t.error}catch{$('#delivery-status').textContent=t.error}finally{button.disabled=false}});
 $('#branch-options').addEventListener('change',e=>form.elements.branch.value=e.target.value);
 form.addEventListener('submit',e=>{e.preventDefault();const phone=form.elements.phone;const digits=phone.value.replace(/\D/g,'');phone.setCustomValidity(/^(?:380\d{9}|0\d{9})$/.test(digits)?'':t.invalid);if(!form.reportValidity())return;draft=Object.fromEntries(new FormData(form));if(items().length!==rows.length||items().some(x=>!Number.isInteger(x.qty)||x.qty<1||rows.filter(r=>r.variant===x.variant).reduce((n,r)=>n+r.qty,0)>x.v.stock)){alert(t.stock);return}review()});form.elements.phone.addEventListener('input',()=>form.elements.phone.setCustomValidity(''));
}
function review(){const t=c();$('#checkout-content').innerHTML='<h2 id="checkout-title">'+t.review+'</h2>'+summary()+'<dl class="checkout-review"><dt>'+t.contact+'</dt><dd>'+esc(draft.name)+'<br>'+esc(draft.phone)+'</dd><dt>'+t.delivery+'</dt><dd>'+ (draft.carrier==='nova'?'Нова пошта':'Укрпошта')+'<br>'+esc(draft.city)+', '+esc(draft.branch)+(draft.carrier==='ukr'?' · '+esc(draft.postcode):'')+'</dd><dt>'+t.payment+'</dt><dd>'+t.cod+'</dd>'+(draft.comment?'<dt>'+t.comment+'</dt><dd>'+esc(draft.comment)+'</dd>':'')+'</dl><p class="checkout-notice" role="status">'+t.pending+'</p><div class="checkout-review-actions"><button id="edit-order" class="checkout-secondary">'+t.back+'</button><a class="checkout-start" href="tel:+380672504939">'+t.contactShop+'</a></div>';$('#edit-order').addEventListener('click',render)}
document.addEventListener('click',async e=>{if(!e.target.closest('[data-checkout]'))return;lang=document.documentElement.lang in copy?document.documentElement.lang:'uk';rows=readCart();if(!rows.length)return;try{const r=await fetch('products.json?v=shop-20260929b');if(!r.ok)throw Error();catalog=await r.json()}catch{return}$('#shop-dialog').close();render();$('#checkout-dialog').showModal()});
$('#close-checkout').addEventListener('click',()=>$('#checkout-dialog').close());
fetch('/api/commerce').then(r=>r.ok?r.json():null).then(x=>{if(x)config=x.delivery}).catch(()=>{});
